def levenshtein(source, target):
    # Base cases: one string is empty
    if source == '':
        return len(target)
    if target == '':
        return len(source)

    # If the first characters match, no cost for this position
    if source[0] == target[0]:
        return levenshtein(source[1:], target[1:])

    # If the first characters differ, consider insertion, deletion, and substitution
    return 1 + min(
        levenshtein(source,     target[1:]),  # Insertion
        levenshtein(source[1:], target),      # Deletion
        levenshtein(source[1:], target[1:])   # Substitution
    )

